def intersect_intervals(s1: int | None, e1: int | None, s2: int | None, e2: int | None) -> tuple[int | None, int | None] | None:
    """Computes intersection of two intervals supporting unbounded endpoints (None).
    Returns (start, end) of intersection or None if empty.
    """
    # Compute max of starts
    if s1 is None and s2 is None:
        start = None
    elif s1 is None:
        start = s2
    elif s2 is None:
        start = s1
    else:
        start = max(s1, s2)

    # Compute min of ends
    if e1 is None and e2 is None:
        end = None
    elif e1 is None:
        end = e2
    elif e2 is None:
        end = e1
    else:
        end = min(e1, e2)

    # Check for empty intersection
    if start is not None and end is not None and start >= end:
        return None

    return (start, end)
